const porSku = {};
for (const item of $input.all()) {
  const j = item.json;
  const sku = String(j.item_id);
  if (!sku || sku === 'undefined') continue;
  if (!porSku[sku]) porSku[sku] = [];
  porSku[sku].push({ f: String(j.date), v: Number(j.sales) || 0 });
}
const series = {};
for (const sku of Object.keys(porSku)) {
  const arr = porSku[sku].sort((a, b) => (a.f < b.f ? -1 : 1));
  series[sku] = { ventas: arr.map(x => x.v), fechas: arr.map(x => x.f) };
}
return [{ json: { series: series } }];

const STOCK = {FOODS_2_019:41,FOODS_2_197:107,FOODS_3_064:213,FOODS_3_080:225,FOODS_3_090:159,FOODS_3_099:83,FOODS_3_120:378,FOODS_3_252:465,FOODS_3_282:56,FOODS_3_295:132,FOODS_3_499:95,FOODS_3_501:283,FOODS_3_511:74,FOODS_3_555:109,FOODS_3_586:291,FOODS_3_587:420,FOODS_3_681:66,FOODS_3_714:94,FOODS_3_739:80,FOODS_3_741:183};
const d = $input.first().json;
const pron = d.pronosticos || {};
const presion = d.presion_quiebre_por_producto || {};
const todos = [];
for (const sku of Object.keys(pron)) {
  const p = pron[sku];
  const demanda7 = p.demanda_total;
  const stock = (STOCK[sku] != null) ? STOCK[sku] : Math.round((p.demanda_prom_dia || 0) * 5);
  const punto = demanda7;
  todos.push({ item_id: sku, demanda_7d: demanda7, demanda_prom_dia: p.demanda_prom_dia, stock_actual: stock, punto_reorden: Math.round(punto * 10) / 10, reponer: (stock < punto), cantidad_sugerida: Math.max(0, Math.round(punto - stock)) });
}
const aReponer = todos.filter(x => x.reponer).sort((a, b) => b.cantidad_sugerida - a.cantidad_sugerida);
const reclamos = Object.keys(presion).map(k => k + ' (' + presion[k] + ')');
return [{ json: { tienda: 'CA_1', lead_time_dias: 7, total_sku: todos.length, n_reponer: aReponer.length, items: aReponer, reclamos_quiebre: reclamos } }];

